local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["9700cf20340b4c8a"] = { "C... ciao, {name}. Scusa, mi sto riprendendo dalle ferite.\n\nQuei Crociati Scarlatti sono più duri di quanto pensassi. Per poco non mi facevano fuori.\n\nAnche tu fai attenzione. Non vorrei vederti cadere in una loro imboscata.", "." },
  ["970346e0fbec32a5"] = { "Ahimè, sembra sempre così. Io, come il resto del ⟦Cenarion Circle=Circolo Cenariano⟧, davo per scontato che la creazione di Milli fosse stata distrutta durante la Guerra degli Antichi. Ho scoperto che è tutt'altro che vero.\n\nIl Fruit of Fertility è sopravvissuto... anche se ora è noto come Vil Vite. Lo sta corrompendo il signore demoniaco di quella sezione di Eldre'Thalas, Alzzin the Wildshaper.", "." },
  ["97073f2b490495a7"] = { "Già. Non hai mai sentito parlare di Ironfoe? Il leggendario martello ammazza-orchi? Già, già, era il martello del vecchio Windsor. Mi ha detto che Franclorn Forgewright in persona aveva forgiato quel martello per il suo trisnonno. IL Franclorn Forgewright: il ⟦Dark Iron=Ferroscuro⟧ responsabile dell'archimetenc... delle costruzioni in pietra. Diceva anche che il martello aveva un gemello che Franclorn tenne per sé. Mi pare lo chiamasse Ironfel o qualcosa del genere.", "." },
  ["9713dc320f8758fe"] = { "*coff* chi va là? *coff*", "." },
  ["971b369e6b51381f"] = { "Come desideri, Eitrigg.", "." },
  ["97201551951f4ba5"] = { "La Royal Apothecary Society risponderà alla chiamata della Dama Oscura per scoprire la Nuova Piaga e scacciare Arthas e il suo empio esercito del Flagello dal mondo una volta per tutte.", "." },
  ["97226b504838e6a3"] = { "Hai la mia più profonda gratitudine, {name}. Ti ringrazio.", "." },
  ["9725efc1cd67300d"] = { "Ah, <uno/una> <Stregone/Strega> come me, che ha dato prova del proprio valore, almeno in qualche misura.\n\nÈ un piacere fare la tua conoscenza. Mi chiamo Menara Voidrender... e non senza una buona ragione.\n\nSembri abbastanza potente ed erudit<o/a> perché altri strumenti... strumenti più potenti... siano ben accetti e non affidati in modo sconsiderato. Se è così, continua a parlare con me. Altrimenti, beh, conosci la strada per tornare al molo e poi giù nell'oceano.", "." },
  ["9726671842ae8465"] = { "Successo! Evviva! La fonte di energia ha ripristinato la collana!", "." },
  ["972b0df0ea5fcd69"] = { "Va bene, {name}. Seguimi fino alla grotta, dove cercherò di imbrigliare il potere della pietra runica in questi occhialoni.", "." },
  ["974bc49608caa9bd"] = { "Ahah! Che divertente! Divertente umano di legno!", "." },
  ["9753571fd07eaacf"] = { "Sei tornat<o/a> e vedo nei tuoi occhi che hai molto da raccontarmi, {name}. Pensiamo prima alla tua ricompensa.", "." },
  ["9756791b5791af82"] = { "Cho'Rush morire! ORA TU MUORI!", "." },
  ["975d7d769bd541cd"] = { "D'accordo, adesso firmo i permessi. Portateli qui davanti, vermi.", "." },
  ["97632678c878062f"] = { "Mille grazie, {name}. Con queste corna farò una fortuna!", "." },
  ["976cb22fe97b0574"] = { "Fregata in vista! È un vascello degli Orchi, senza dubbio! Fuoco!", "." },
  ["976dcf15d3a8a0e7"] = { "È Vesprystus che cerchi. Sorveglia gli ippogrifi che vanno e vengono dalla base di Teldrassil. Lo troverai oltre il portale nella parte occidentale di Darnassus, che ti porterà a ⟦Rut'theran Village=Rut'theran⟧.", "." },
  ["977086e334e98de7"] = { "Molto bene, {name}.", "." },
  ["977271405ba4726f"] = { "Noi sapere dove sono! Edificio col teschio in ⟦Magic Quarter=Quartiere della Magia⟧, su anello esterno di città.", "." },
  ["977af7d000482995"] = { "No, Vaelan, no.", "." },
  ["9780a82aa0087a4e"] = { "Uno gnomo? Che cosa patetica. Affrontami, demone!", "." },
  ["9781bdf54cc60cfc"] = { "Credo che Plugger abbia riempito troppo uno dei suoi barili. Sembra sul punto di esplodere!", "." },
  ["9785a87073eaac42"] = { "Prendi una ⟦Candle of Beckoning=Candela del Richiamo⟧ da questa cassa, {name}.", "." },
  ["9788d47e85c5755c"] = { "Dove sono finiti gli altri?", "." },
  ["97896d720406d851"] = { "Tu presto morto!", "." },
  ["978bde2dba55fec1"] = { "Continua così, {name}, e ti insegnerò le buone maniere a suon di botte.", "." },
  ["9790f5a714ee57d3"] = { "Bah, non è qui. Dove avrò messo quel dannato coso l'ultima volta?", "." },
  ["9798632be84f6105"] = { "Che istruttore di classe cerchi, eh?", "." },
  ["9798a0cb78c4f816"] = { "Ti prego, continua.", "." },
  ["97b6aead5f9aefbf"] = { "Abbiamo già un vincitore per la nostra gara, ma Jang è disposto a comprare qualsiasi Spigola Screziata tu abbia pescato!\n\nC'è sempre domenica prossima per mostrare la tua abilità nella Pesca!", "." },
  ["97b6ed07b571604f"] = { "%s si attiverà tra 5 secondi!", "." },
  ["97b7c189533bed0f"] = { "Tra il passaggio arancione e quello viola, vicino alle porte di Maraudon, troverai un terzo sentiero.\n\nLo scettro che tieni in mano è la chiave.", "." },
  ["97b8b0e5497984b0"] = { "Gubber, non ho una canna da pesca.", "." },
  ["97c4bab9f3d6df5d"] = { "{name}, fai molta attenzione a ciò che faccio e segui le mie istruzioni alla lettera. Non dare ascolto alle mie parole significa firmare la tua condanna a morte, perché il ⟦Taskmaster Fizzule=Coordinatore Fizzule⟧ è MOLTO esperto nelle vie del guerriero e dell'assassino.", "." },
  ["97ce6a44519147e6"] = { "Ora scaldiamo queste scaglie...", "." },
  ["97cea19152371670"] = { "Molto bene, {name}. Userò l'Oggetto Intriso di Incubi per evocare Eranikus.", "." },
  ["97dbbfee9c321779"] = { "Ne hai abbastanza di quei drink da incantatori smidollati? Prova qualcosa di più forte al Pig and Whistle!", "." },
  ["97e2b67f9c561a09"] = { "Tra Bixi e Buliwyf, non ci sono molte armi con cui non abbiano avuto il piacere di affettare o spaccare un orco. Li trovi alla bottega d'armi Timberline Arms, se ti serve un addestramento.", "." },
  ["97e32472dd30b69a"] = { "Hai caldo? Vieni a rinfrescarti al Pig and Whistle!", "." },
  ["97eaacc69101c0c7"] = { "%s alza la mano e poi la abbassa.", "." },
  ["97ef7b982fbb9053"] = { "Salute, {class}! Le nostre scorte sono abbondanti e siamo pronti a lanciare un assalto via terra attraverso il ⟦Field of Strife=Pian della Discordia⟧. Forse, se la tua fama fosse maggiore, ti affiderei gli ordini d'assalto.\n\nQuindi vai là fuori e combatti l'⟦Alliance=Alleanza⟧! Dimostrami che sei un membro fidato e capace dell'⟦Horde=Orda⟧!", "." },
  ["97f376be7e4f6c23"] = { "Conosco solo una persona più esperta di me nell'arte della sartoria. L'ultima volta che ne ho sentito parlare si trovava all'⟦Theramore Isle=Isola di Theramore⟧. È lui che dovresti cercare.", "." },
  ["97f8aa037e28192d"] = { "Il tessuto di cui è intessuto il nostro mondo è delicatissimo. Basta un po' di conoscenza, e l'applicazione di tale conoscenza, per strapparlo. È così che nascono le fratture.", "." },
})
